declare(strict_types=1);require_once __DIR__.'/seguridad.php';simceRequireRole(array('colegio_admin','docente'));$db=simceDatabase();$id=(int)($_GET['id']??0);$s=$db->prepare('SELECT ruta FROM pruebas WHERE id=:id AND colegio_id=:c AND activa=1');$s->execute(array(':id'=>$id,':c'=>simceTenantId()));$row=$s->fetch();if(!$row){http_response_code(404);exit('Prueba no encontrada.');}$path=realpath(__DIR__.'/'.str_replace('/',DIRECTORY_SEPARATOR,$row['ruta']));$root=realpath(__DIR__);if(!$path||!$root||strpos($path,$root.DIRECTORY_SEPARATOR)!==0||!is_file($path)){http_response_code(404);exit('Archivo no encontrado.');}header('Content-Type:text/html;charset=utf-8');header('Cache-Control:no-store');readfile($path);
